## isonim/dsl/tailwind.nim
##
## Compile-time Tailwind CSS class resolver.
##
## Loads the style mapping generated by the real Tailwind CSS CLI
## (via tools/tailwind-extract.mjs) and expands class strings to
## (CSS-property, value) pairs at compile time.
##
## Build pipeline:
##   1. `node tools/tailwind-extract.mjs` — runs Tailwind CSS, produces
##      build/tailwind.css (for web) and build/tailwind-styles.json (for native)
##   2. This module loads tailwind-styles.json at Nim compile time
##   3. The ui macro calls expandTailwindClasses() to expand class
##      attributes to setStyle calls
##
## On web (-d:js), class attributes pass through to the browser
## where build/tailwind.css provides the styles.

import std/[json, tables, strutils, os]

# ===========================================================================
# Load the Tailwind style map at compile time from the JSON file
# ===========================================================================

## Each consuming app drives its own extract so the content-scan set covers
## that app's source.  Pass an absolute path via
## ``-d:tailwindStylesPathOverride=<path>`` (preferred) when invoking nim;
## the empty default falls back to isonim's own ``build/`` so isonim's own
## dev/test compiles keep working without the flag.
const tailwindStylesPathOverride* {.strdefine.}: string = ""

const defaultTailwindJsonPath = block:
  const path = currentSourcePath().replace('\\', '/')
  path.parentDir().parentDir().parentDir().parentDir() / "build" / "tailwind-styles.json"

const tailwindJsonPath =
  if tailwindStylesPathOverride.len > 0: tailwindStylesPathOverride
  else: defaultTailwindJsonPath

when defined(nimscript) or defined(js):
  import std/compilesettings

  const tailwindMetadataProgram = """
import std/os
proc namedLink(path: string): bool =
  when buildOS == "windows":
    # The native existence queries use GetFileAttributes, which describes
    # the named link rather than requiring its target to be accessible.
    false
  elif buildOS in ["linux", "macosx", "freebsd", "openbsd", "netbsd",
                  "dragonfly", "solaris", "aix", "haiku", "android"]:
    let probe = gorgeEx("[ -L " & quoteShellPosix(path) & " ]", "", "")
    if probe.exitCode notin [0, 1]:
      raise newException(IOError, "Tailwind link query failed: " & probe.output)
    probe.exitCode == 0
  else:
    raise newException(IOError, "Unsupported Tailwind metadata host: " & buildOS)
proc mustRead(path: string): bool =
  if fileExists(path) or dirExists(path) or namedLink(path):
    return true
  let parent = path.parentDir()
  if fileExists(parent) or namedLink(parent):
    return true
  if dirExists(parent):
    # Keep the raw /. component: joining/normalizing it loses the actual
    # search-permission check of an existing but inaccessible directory.
    if not dirExists(parent & "/."):
      return true
    for _, name in walkDir(parent, relative = true):
      if name == path.extractFilename():
        return true
  else:
    for _, name in walkDir(parent.parentDir(), relative = true):
      if name == parent.extractFilename():
        return true
  false
proc query(path: string) =
  if mustRead(path): echo "isonim-tailwind-map-v1:read"
  else: echo "isonim-tailwind-map-v1:absent"
"""

  proc quoteCompilerCommand(compiler: string; arguments: openArray[string]): string
      {.compileTime.} =
    ## JS's hostOS describes the target, not the compiler's native host.
    ## Recognize native absolute executable paths and use the public quoting
    ## functions for their command-line form; never guess from environment.
    let drivePath = compiler.len >= 3 and compiler[0] in {'a'..'z', 'A'..'Z'} and
      compiler[1] == ':' and compiler[2] in {'/', '\\'}
    let uncParts = compiler.split('\\')
    let uncPath = compiler.startsWith("\\\\") and uncParts.len >= 5 and
      uncParts[2].len > 0 and uncParts[3].len > 0 and uncParts[^1].len > 0
    let posixPath = compiler.startsWith("/") and not compiler.startsWith("//")
    if not (drivePath or uncPath or posixPath):
      raise newException(IOError, "Unknown absolute Nim compiler path: " & compiler)
    for arg in @[compiler] & @arguments:
      if result.len > 0: result.add ' '
      result.add(if posixPath: quoteShellPosix(arg) else: quoteShellWindows(arg))

  proc defaultTailwindMapMissing(): bool {.compileTime.} =
    ## Nim 2.0's JS VM has no public file-existence API. Ask the very same
    ## compiler in NimScript mode, which has host metadata operations. The
    ## fixed program needs no generated file, C compiler or installed helper.
    let library = querySetting(SingleValueSetting.libPath)
    if library.len == 0:
      raise newException(IOError, "Nim did not report its selected standard library")
    # Nim expands $ in path options separately from the host command-line
    # quoting. Double literal dollars when forwarding the resolved lib path.
    let command = quoteCompilerCommand(getCurrentCompilerExe(), [
      "e", "--hints:off", "--warnings:off", "--skipUserCfg:on",
      "--skipParentCfg:on", "--skipProjCfg:on", "--lib:" & library.replace("$", "$$"),
      "--eval:" & tailwindMetadataProgram & "\nquery(" & defaultTailwindJsonPath.escape & ")"])
    # Metadata must be measured afresh when files or permissions change.
    let metadata = gorgeEx(command, "", "")
    if metadata.exitCode != 0:
      raise newException(IOError, "Tailwind metadata query failed: " & metadata.output)
    case metadata.output
    of "isonim-tailwind-map-v1:absent", "isonim-tailwind-map-v1:absent\n",
        "isonim-tailwind-map-v1:absent\r\n": true
    of "isonim-tailwind-map-v1:read", "isonim-tailwind-map-v1:read\n",
        "isonim-tailwind-map-v1:read\r\n": false
    else:
      raise newException(IOError, "Invalid Tailwind metadata response: " & metadata.output)

  const tailwindJsonStr =
    when tailwindStylesPathOverride.len > 0: staticRead(tailwindJsonPath)
    elif compiles(block:
      const readableDefault = staticRead(defaultTailwindJsonPath)
      discard readableDefault):
      staticRead(defaultTailwindJsonPath)
    elif defaultTailwindMapMissing(): "{}"
    else: staticRead(tailwindJsonPath)
  const hasTailwindStyles* = tailwindJsonStr != "{}"
else:
  when fileExists(tailwindJsonPath):
    const tailwindJsonStr = staticRead(tailwindJsonPath)
    const hasTailwindStyles* = true
  else:
    const tailwindJsonStr = "{}"
    const hasTailwindStyles* = false

proc buildStyleMap(): tuple[
    styles: Table[string, seq[tuple[prop, val: string]]];
    variants: Table[string, string];
    units: Table[string, seq[tuple[prop, unit: string]]]
] {.compileTime.} =
  let j = parseJson(tailwindJsonStr)
  for className, propsNode in j:
    var styles: seq[tuple[prop, val: string]]
    for prop, val in propsNode:
      if prop == "variant":
        result.variants[className] = val.getStr()
      elif prop == "units":
        for uprop, uval in val:
          result.units.mgetOrPut(className, @[]).add((uprop, uval.getStr()))
      else:
        styles.add((prop, val.getStr()))
    result.styles[className] = styles

const tailwindMap = buildStyleMap()
const tailwindStyles* = tailwindMap.styles
const tailwindVariants* = tailwindMap.variants
  ## Variants mode: class name → variant (`sm`, `dark`, `hover`), only for entries the
  ## extractor tagged with `--variants`. Empty without the flag.
const tailwindUnits* = tailwindMap.units
  ## Variants mode: class name → stripped `px` units per prop. Empty without the flag.

# ===========================================================================
# Public API — called by the DSL macro at compile time
# ===========================================================================

proc parseTailwindClass*(cls: string): seq[tuple[prop, val: string]] =
  ## Look up a single Tailwind utility class in the style map.
  ## Returns empty seq for unrecognized classes.
  if cls in tailwindStyles:
    tailwindStyles[cls]
  else:
    @[]

proc expandTailwindClasses*(classStr: string): seq[tuple[prop, val: string]] =
  ## Parse a space-separated Tailwind class string and expand all utilities
  ## to CSS property/value pairs. Unrecognized classes are silently skipped.
  for cls in classStr.splitWhitespace():
    let styles = parseTailwindClass(cls)
    result.add(styles)

when defined(isonimTailwindVariants):
  proc isBareNumber(s: string): bool {.compileTime.} =
    ## True when the extractor's px-strip pattern could have produced `s`
    ## (`^[\d.]+$`, mirroring `tailwind-extract.mjs`), so a recorded unit
    ## may be appended.
    if s.len == 0:
      return false
    for c in s:
      if c notin {'0' .. '9', '.'}:
        return false
    return true

proc expandTailwindClassesCompileTime*(classStr: string): seq[tuple[prop, val: string]]
    {.compileTime.} =
  ## Compile-time version for use inside macros.
  when defined(isonimTailwindVariants):
    # Variants opt-in: the switch is the global `-d:isonimTailwindVariants`
    # the email build sets in config.nims — not a per-renderer hook
    # like the static vocabulary — because the expansion runs once at macro-expansion
    # time, before any renderer type is known.
    for cls in classStr.splitWhitespace():
      if cls in tailwindStyles:
        var prefix = ""
        if cls in tailwindVariants:
          prefix = "@" & tailwindVariants[cls] & ":"
        for (prop, val) in tailwindStyles[cls]:
          var v = val
          if isBareNumber(v) and cls in tailwindUnits:
            for u in tailwindUnits[cls]:
              if u.prop == prop:
                v = v & u.unit
                break
          result.add((prefix & prop, v))
  else:
    for cls in classStr.splitWhitespace():
      if cls in tailwindStyles:
        result.add(tailwindStyles[cls])
